from typing import List

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)

        def sort_diagonal(r: int, c: int, reverse: bool) -> None:
            cells = []
            i, j = r, c
            while i < n and j < n:
                cells.append(grid[i][j])
                i += 1
                j += 1

            cells.sort(reverse=reverse)

            i, j = r, c
            k = 0
            while i < n and j < n:
                grid[i][j] = cells[k]
                k += 1
                i += 1
                j += 1

        # Bottom-left triangle, including main diagonal: non-increasing.
        for r in range(n):
            sort_diagonal(r, 0, True)

        # Top-right triangle: non-decreasing.
        for c in range(1, n):
            sort_diagonal(0, c, False)

        return grid
